python3 - <<'EOF'
PATH='/home/lane/MythosMini/slm_alliance.html'
src=open(PATH).read()

src=src.replace('<feTurbulence type="turbulence" baseFrequency="0.004" numOctaves="2" seed="1" result="noise"/>',
                '<feTurbulence type="turbulence" baseFrequency="0.004" numOctaves="1" seed="1" result="noise"/>')
src=src.replace('scale="60"','scale="45"')

old='''        // Anthropic-style boil: nudge turbulence baseFrequency every 100ms.
        if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
          const turb = svg.querySelector('#logoBoil feTurbulence');
          const base = 0.004;
          const offsets = [-0.002, 0.001, -0.001, 0.002];
          let tick = 0;
          setInterval(() => {
            tick = (tick + 1) % offsets.length;
            turb.setAttribute('baseFrequency', (base + offsets[tick]).toFixed(4));
          }, 100);
        }

'''
new='''        // Anthropic-style boil: ease turbulence baseFrequency toward a new
        // random target a few times per second, updating at ~20fps.
        if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
          const turb = svg.querySelector('#logoBoil feTurbulence');
          const base = 0.004;
          const spread = 0.0016;
          let from = base, to = base + spread, segStart = performance.now();
          const segDur = 420;            // ms per redraw glide
          let lastFrame = 0;
          const ease = t => t < 0.5 ? 2*t*t : 1 - Math.pow(-2*t + 2, 2) / 2;
          function loop(now) {
            requestAnimationFrame(loop);
            if (now - lastFrame < 50) return;   // cap filter recomputes at 20fps
            lastFrame = now;
            let t = (now - segStart) / segDur;
            if (t >= 1) {
              from = to;
              to = base + (Math.random() * 2 - 1) * spread;
              segStart = now;
              t = 0;
            }
            const f = from + (to - from) * ease(Math.min(t, 1));
            turb.setAttribute('baseFrequency', f.toFixed(5));
          }
          requestAnimationFrame(loop);
        }

'''
assert old in src
src=src.replace(old,new)
open(PATH,'w').write(src)
print('OK')
